<script setup lang="ts">import {computed} from "vue";import {Laptop,ShieldAlert} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import ValidationMessage from "@/components/zs/ValidationMessage.vue";import {useAsyncData} from "@/composables/useAsyncData";import {platformRepository} from "@/services/platform/repository";import {useCompanyStore} from "@/stores/company";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta('Security Center','Recent sessions, security events and invitations for the active company.');const company=useCompanyStore(),state=useAsyncData(()=>platformRepository.security(company.activeCompanyId),{watch:[()=>company.activeCompanyId]}),sessions=computed(()=>state.data.value?.sessions??[]),events=computed(()=>state.data.value?.events.data??[]),sessionColumns:Column[]=[{key:'device',header:'Session'},{key:'user_id',header:'User ID'},{key:'ip_address',header:'IP address'},{key:'last_activity',header:'Last active'},{key:'actions',header:''}],eventColumns:Column[]=[{key:'created_at',header:'Time'},{key:'type',header:'Event'},{key:'result',header:'Result'},{key:'ip_address',header:'IP address'}];async function revoke(id:string){await platformRepository.revokeSession(company.activeCompanyId,id);showToast('Session revoked');await state.refresh()}async function revokeOthers(){await platformRepository.revokeOtherSessions(company.activeCompanyId);showToast('Other sessions revoked');await state.refresh()}</script>
<template><AppShell><PageHeader title="Security Center" description="Company-scoped authentication and administrative security evidence"><template #actions><ZButton v-if="state.data.value?.sessions_supported" variant="outline" @click="revokeOthers">Revoke my other sessions</ZButton></template></PageHeader><ValidationMessage :message="state.error.value?.message"/><Panel title="Active and recent sessions" :description="state.data.value?.sessions_supported?'Database-backed session management is available.':'The configured session driver does not expose revocable sessions.'"><DataTable :columns="sessionColumns" :rows="sessions" :min-width="850"><template #device="{row}"><div class="flex items-center gap-2"><Laptop class="size-4 text-content-muted"/><span class="max-w-sm truncate text-xs">{{row.user_agent??'Unknown client'}}</span></div></template><template #user_id="{row}"><span class="num">{{row.user_id}}</span></template><template #ip_address="{row}">{{row.ip_address??'—'}}</template><template #last_activity="{row}">{{new Date(row.last_activity*1000).toLocaleString()}}</template><template #actions="{row}"><ZButton v-if="company.hasPermission('platform.security.manage')" variant="ghost" @click="revoke(row.id)">Revoke</ZButton></template></DataTable></Panel><Panel class="mt-4" title="Security events"><DataTable :columns="eventColumns" :rows="events" :min-width="760"><template #created_at="{row}">{{new Date(row.created_at).toLocaleString()}}</template><template #type="{row}"><span class="inline-flex items-center gap-2 font-medium text-content"><ShieldAlert class="size-4 text-content-muted"/>{{row.type}}</span></template><template #result="{row}"><StatusBadge :status="row.result.toLowerCase()"/></template><template #ip_address="{row}">{{row.ip_address??'—'}}</template></DataTable></Panel></AppShell></template>
